/** A text size of the snapshot matrix, and the font scale that gives it. */
internal enum class SnapshotTextSize(val fontScale: Float) {
    /** The size each platform starts with. */
    Default(1f),
    /** The largest size the snapshots draw: twice the root font size on the web, the largest accessibility size of Dynamic Type on iOS, and the largest font scale on Android. */
    Largest(2f),
}

/** A snapshot of the matrix: all the examples of a component, drawn together in one theme. */
