    /** Names the snapshot, and its baseline image. */
    val id: String,
    val mode: ColorMode,
    /** A BCP 47 language tag. "en-XA" is the expanded pseudo-locale. */
    val locale: String,
    val rightToLeft: Boolean,
    val textSize: SnapshotTextSize,
)

